let toastTimer;
function toast(message,error=false){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').className=`toast${error?' error':''}`;toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),error?5000:2600);}
const view=new TrafficScene($('#stage'),{onError:(message)=>toast(message,true),onReady:()=>$('#loading-note').classList.add('hidden')});window.__view=view;
view.fit();

function refresh(){
  const edit=state.mode==='edit',run=state.mode==='run',garage=state.mode==='garage';
  $('#app').classList.toggle('is-running',run);$('#app').classList.toggle('is-facility-tool',state.tool==='facility');if(!run)$('#incident-pill').classList.add('hidden');
  $('.template-entry').classList.toggle('hidden',!edit);
  $('#mode-label').textContent=garage?'车库':edit?'设计':state.mode==='transition'?'准备':'运行';
  $('#editor-bottom').classList.toggle('hidden',!edit);$('#runtime-bottom').classList.toggle('hidden',!run);$('#hud').classList.toggle('hidden',!run);$('#sim-status').classList.toggle('hidden',!run);$('#garage-overlay').classList.toggle('hidden',!garage);$('#garage-return').classList.toggle('hidden',!garage);$('#menu-button').classList.toggle('hidden',garage);
  for(const id of ['traffic-status','traffic-legend','demand-pill'])$(`#${id}`).classList.toggle('hidden',!run);$('#demand-pill-value').textContent=state.settings.demand;
  $('#command-rail').classList.toggle('hidden',garage||state.mode==='transition');$('#tool-hint').classList.toggle('hidden',!edit);$('#view-toggle').classList.toggle('hidden',!edit);$('#view-toggle').innerHTML=`<span class="view-full">${state.editView==='2d'?'3D 预览':'2D 俯视'}</span><span class="view-compact">${state.editView==='2d'?'3D':'2D'}</span>`;$('#view-toggle').setAttribute('aria-label',state.editView==='2d'?'切换三维预览':'切换二维俯视');$('#heatmap-toggle').classList.toggle('hidden',!run);$('#heatmap-toggle').classList.toggle('active',state.heatmap);view.showHeatmap=state.heatmap;view.environment(state.settings);view.setNavigationTool(state.tool);
  $('#road-tools').classList.toggle('hidden',state.buildTab!=='roads');$('#facility-tools').classList.toggle('hidden',state.buildTab!=='facilities');$('#road-modes').classList.toggle('hidden',state.buildTab!=='roads');$('#snap-strip').classList.toggle('hidden',state.buildTab!=='roads');$$('[data-build-tab]').forEach(b=>b.classList.toggle('active',b.dataset.buildTab===state.buildTab));$$('[data-shape]').forEach(b=>b.classList.toggle('active',b.dataset.shape===state.shape));$$('[data-snap]').forEach(b=>{b.classList.toggle('active',state[b.dataset.snap]);b.setAttribute('aria-pressed',!!state[b.dataset.snap]);});$$('[data-facility-type]').forEach(b=>b.classList.toggle('active',state.tool==='facility'&&b.dataset.facilityType===state.facilityType));$('#new-road-spec').textContent=`${state.newLanesForward+state.newLanesBackward} 车道 · ${state.newRoadSpeed} km/h`;
  $('#view-label').classList.toggle('hidden',garage);$('.camera-controls').classList.toggle('hidden',garage);
  $('#view-label').textContent=view.fallback?'二维兼容模式':edit?`${state.editView==='2d'?'俯视建造':state.tool==='select'?'三维观察 · 左键拖动旋转':'三维建造 · 左键建路，右键旋转'} · 中键平移 · 滚轮缩放`:'三维运行 · 左键拖动旋转 · 中键平移';
  $$('.undo-button').forEach(b=>{b.disabled=!edit||!state.history.length;b.classList.toggle('hidden',garage);});$$('.redo-button').forEach(b=>{b.disabled=!edit||!state.future.length;b.classList.toggle('hidden',garage);});
  const validity=validateNetwork(state.network);$('#start-button').disabled=!validity.valid;$('#connection').classList.toggle('valid',validity.valid);$('#connection-text').textContent=state.anchor?'继续画路，Esc 结束本段':state.classicLabel&&validity.valid?`${state.classicLabel} · 已接通`:validity.reason;$('#connection .status-dot').textContent=validity.valid?'✓':'·';
  $$('[data-tool]').forEach(b=>{b.classList.toggle('active',b.dataset.tool===state.tool);b.setAttribute('aria-pressed',b.dataset.tool===state.tool);});
  $('#pause-button').innerHTML=icon(state.running?'pause':'play');$('#pause-button').setAttribute('aria-label',state.running?'暂停':'继续');$$('[data-speed]').forEach(b=>b.classList.toggle('active',Number(b.dataset.speed)===state.speed));
  view.canvas.style.cursor=edit?(state.tool==='erase'?'not-allowed':state.editView==='3d'&&state.tool==='select'?'grab':'crosshair'):'grab';
  requestAnimationFrame(()=>{if(edit){$('#editor-bottom').style.paddingTop=`${$('#connection').offsetHeight+12}px`;$('#tool-hint').style.bottom=`${$('#editor-bottom').offsetHeight+(innerWidth<600?14:26)+12}px`;}view.resize();});
}
function commit(network){network=realignTrafficLights(network);resetClassic();editor?.cancel(true);state.history.push(clone(state.network));if(state.history.length>60)state.history.shift();state.future=[];state.network=network;state.selectedRoad=null;state.selectedNode=null;view.setNetwork(network);refresh();}
function undo(){if(state.mode!=='edit'||!state.history.length)return;resetClassic();editor.cancel(true);state.future.push(clone(state.network));state.network=realignTrafficLights(state.history.pop());state.anchor=null;view.setPreview([]);view.setNetwork(state.network);refresh();}
function redo(){if(state.mode!=='edit'||!state.future.length)return;resetClassic();editor.cancel(true);state.history.push(clone(state.network));state.network=realignTrafficLights(state.future.pop());state.anchor=null;view.setPreview([]);view.setNetwork(state.network);refresh();}
function setTool(tool){if(state.mode!=='edit')return;closePanel();state.tool=tool;editor.setTool(tool);refresh();}
function nearestNode(point,radius=12){let best=null,dist=radius;for(const n of state.network.nodes){const d=Math.hypot(n.x-point.x,n.z-point.z);if(d<dist){best=n;dist=d;}}return best;}
function nearestRoad(point,max=7){let best=null,distance=max;for(const r of state.network.roads){const a=state.network.nodes.find(n=>n.id===r.a),b=state.network.nodes.find(n=>n.id===r.b);const dx=b.x-a.x,dz=b.z-a.z,t=Math.max(0,Math.min(1,((point.x-a.x)*dx+(point.z-a.z)*dz)/(dx*dx+dz*dz)));const d=Math.hypot(point.x-a.x-t*dx,point.z-a.z-t*dz);if(d<distance){best=r;distance=d;}}return best;}
const editor=new RoadEditor({view,getState:()=>state,commit,changed:refresh,toast,selectRoad:id=>state.mode==='run'?openRoadTraffic(id):openRoad(id),selectNode:id=>state.mode==='run'?openRoadTraffic(state.network.roads.find(r=>r.a===id||r.b===id)?.id):openSignal(id),selectFacility:id=>sandbox.inspectFacility(id),selectVehicle:id=>sandbox.inspectVehicle(id),selectIncident:id=>sandbox.inspectIncident(id),hint:updateToolHint});
const sandbox=new SandboxPanels({getState:()=>state,setPanel,closePanel,commit,toast,updateSettings,view,icon,field,refresh,setTool,openSignal});
const theory=new TheoryGuide(setPanel);
let activeClassic=null;
function resetClassic(){activeClassic=null;state.classicLabel=null;}
const templates=[
  {id:'fork',title:'分岔路网',detail:'主路与绕行支路'},
  {id:'signal',title:'信号交叉口',detail:'带信号控制的交叉路口'},
  {id:'turn-junction',title:'六车道转向路口',detail:'双向三车道 · 左直右自动分配',model:'signal',variant:'balanced',approachLanes:3},
  {id:'roundabout',title:'曲线环岛',detail:'圆弧道路与进出连接'},
  {id:'accident',title:'冲突与事故',detail:'路口冲突及事故情景'},
  {id:'bottleneck',title:'慢行瓶颈',detail:'主路中的低速路段'},
  {id:'braess-closed',title:'Braess · 无捷径',detail:'两条外围路线',model:'braess',variant:'closed'},
  {id:'braess-open',title:'Braess · 有捷径',detail:'增加中间单向连接',model:'braess',variant:'open'},
  {id:'queue-base',title:'瓶颈 · 原始限速',detail:'中段限速 20 km/h',model:'bottleneck',variant:'base'},
  {id:'queue-improved',title:'瓶颈 · 提高限速',detail:'中段限速 60 km/h',model:'bottleneck',variant:'improved'},
  {id:'signal-balanced',title:'信号 · 等分配时',detail:'东西 30 秒 / 南北 30 秒',model:'signal',variant:'balanced'},
  {id:'signal-adjusted',title:'信号 · 东西优先',detail:'东西 45 秒 / 南北 15 秒',model:'signal',variant:'adjusted'}
];
function loadTemplate(id){
  if(state.mode!=='edit')return;const item=templates.find(t=>t.id===id);if(!item)return;
  const network=item.model?createClassicNetwork(item.model,item.variant,{green:45}):createPreset(item.id);
  if(item.approachLanes){for(const r of network.roads){r.lanesForward=item.approachLanes;r.lanesBackward=r.oneWay?0:item.approachLanes;r.width=roadWidth(r);}for(const f of network.facilities||[]){const r=network.roads.find(x=>x.id===f.roadId);if(!r)continue;const p=roadPointAt(network,r,f.s,(f.side||1)*(roadWidth(r)/2+(f.type==='trafficLight'?1.4:1.6)));f.x=p.x;f.z=p.z;if(f.type!=='trafficLight')f.heading=p.yaw;}}
  closePanel();commit(network);state.anchor=null;state.tool='select';
  if(item.model)activeClassic={id:item.model,variant:item.variant};
  state.classicLabel=item.title;editor.defaultHint();view.fit();refresh();toast(`已载入${item.title}，可直接编辑或开始运行`);
}
function updateToolHint({title,detail,valid=true}){$('#tool-hint-title').textContent=title;$('#tool-hint-detail').textContent=detail;$('#tool-hint').dataset.valid=valid;}
const turnOptions=[['auto','自动'],['left','↰ 左转'],['through','↑ 直行'],['right','↱ 右转'],['left,through','左转＋直行'],['through,right','直行＋右转'],['left,through,right','左直右共享']];
function turnFields(prefix,road){const c=laneCounts(road);return ['forward','backward'].map(dir=>{const n=dir==='forward'?c.forward:c.backward,rules=road[dir==='forward'?'turnsForward':'turnsBackward'];return n?`<h4>${dir==='forward'?'正向':'反向'} · 从左到右</h4>${Array.from({length:n},(_,i)=>{const value=rules?.[i]?.length?rules[i].join(','):'auto';return `<label class="turn-row"><span>第 ${i+1} 道</span><select data-turn-form="${prefix}" data-turn-direction="${dir}" data-turn-index="${i}" aria-label="${dir==='forward'?'正向':'反向'}第${i+1}道用途">${turnOptions.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`;}).join('')}`:'';}).join('');}
function readTurns(prefix,dir,count){const inputs=$$(`[data-turn-form="${prefix}"][data-turn-direction="${dir}"]`);const rules=Array.from({length:count},(_,i)=>{const value=inputs[i]?.value||'auto';return value==='auto'?[]:value.split(',');});return rules.some(r=>r.length)?rules:undefined;}
function laneControls(prefix,road){const c=laneCounts(road);return `<div class="lane-presets">${[1,2,3,4,6,8,12,16].map(n=>`<button data-lane-count="${n}" data-lane-form="${prefix}">${n} 车道</button>`).join('')}</div><div class="lane-fields">${field('正向车道',`${prefix}-lanes-forward`,c.forward,1,road.oneWay?16:8)}${field('反向车道',`${prefix}-lanes-backward`,c.backward,road.oneWay?0:1,road.oneWay?0:8)}</div><p class="lane-summary" id="${prefix}-lane-summary">共 ${c.total} 车道 · 铺装宽度 ${roadWidth({...road,lanesForward:c.forward,lanesBackward:c.backward}).toFixed(1)} 米</p><details class="turn-config"><summary>设置直行、左转、右转车道</summary><p>自动模式按下一个路口的可通行方向分配用途。</p><div id="${prefix}-turn-fields">${turnFields(prefix,road)}</div></details>`;}
function laneForm(prefix){const f=Number($(`#${prefix}-lanes-forward`).value),b=Number($(`#${prefix}-lanes-backward`).value),oneWay=prefix==='new'?$('#new-road-oneway').checked:$('#road-direction').value==='one';const road={oneWay,lanesForward:f,lanesBackward:b};laneCounts(road);return{...road,width:roadWidth(road),turnsForward:readTurns(prefix,'forward',f),turnsBackward:readTurns(prefix,'backward',b)};}
function updateLaneForm(prefix,total){const control=prefix==='new'?$('#new-road-oneway'):$('#road-direction');let oneWay=prefix==='new'?control.checked:control.value==='one';if(total===1){oneWay=true;if(prefix==='new')control.checked=true;else control.value='one';}const f=$(`#${prefix}-lanes-forward`),b=$(`#${prefix}-lanes-backward`);if(total!==undefined){f.value=oneWay?total:Math.ceil(total/2);b.value=oneWay?0:Math.floor(total/2);}f.max=oneWay?16:8;b.min=oneWay?0:1;b.max=oneWay?0:8;b.disabled=oneWay;if(oneWay)b.value=0;try{const r=laneForm(prefix);$(`#${prefix}-lane-summary`).textContent=`共 ${r.lanesForward+r.lanesBackward} 车道 · 铺装宽度 ${r.width.toFixed(1)} 米`;$(`#${prefix}-turn-fields`).innerHTML=turnFields(prefix,r);enhanceSelects($(`#${prefix}-turn-fields`));}catch{$(`#${prefix}-lane-summary`).textContent='请填写有效的车道数量';}}
function openConstruction(){setPanel('建造设置',`<h3>新建道路</h3><div class="profile-list">${[['slow','慢行道路',30],['local','普通道路',50],['main','快速道路',70]].map(([type,name,speed])=>`<button data-new-road-type="${type}" data-limit="${speed}" class="${type===state.newRoadType?'active':''}">${name}<strong>${speed}</strong></button>`).join('')}</div>${field('新道路限速 · km/h','new-road-limit',state.newRoadSpeed,5,100)}<h3>车道配置</h3><label class="check-row"><input id="new-road-oneway" type="checkbox" ${state.newOneWay?'checked':''}>单向通行</label>${laneControls('new',{oneWay:state.newOneWay,lanesForward:state.newLanesForward,lanesBackward:state.newLanesBackward,turnsForward:state.newTurnsForward,turnsBackward:state.newTurnsBackward})}<h3>吸附设置</h3>${[['snapNodes','吸附到节点'],['snapRoads','吸附到已有道路'],['snapAngles','方向按 15° 吸附'],['snapGrid','位置按 5 米网格吸附']].map(([key,label])=>`<label class="check-row"><input data-snap-check="${key}" type="checkbox" ${state[key]?'checked':''}>${label}</label>`).join('')}<p>正向指绘制方向。单向最多 16 车道，双向每方向最多 8 车道。</p>`,'<button class="primary" data-action="apply-construction">完成</button>');updateLaneForm('new');}

function setPanel(title,html,footer='<button data-action="close-panel">返回</button>'){
  if(!state.panel){state.panelWasRunning=state.running;state.running=false;}
  state.panel=title;$('#panel-title').textContent=title;$('#panel-body').innerHTML=html;$('#panel-foot').innerHTML=footer;$('#panel').classList.remove('hidden');$('#app').classList.add('has-panel');state.anchor=null;view.setPreview([]);refresh();
  $('#panel-context').classList.toggle('hidden',state.mode!=='run');
  requestAnimationFrame(()=>{view.resize();$('#panel-body').scrollTop=0;enhanceSelects($('#panel-body'));});
}
function closePanel(){if(!state.panel)return;state.panel=null;state.draft=null;$('#panel').classList.add('hidden');$('#app').classList.remove('has-panel');if(state.mode==='run')state.running=state.panelWasRunning;state.panelWasRunning=false;view.setNetwork(state.network,state.selectedRoad);refresh();}
function openMenu(){
  if(state.panel==='菜单'){closePanel();return;}
  const item=(action,label,i)=>`<button data-action="${action}">${icon(i)}<span>${label}</span><span class="arrow">›</span></button>`;
  setPanel('菜单',`<div class="menu-list">${state.mode==='edit'?`<div class="menu-history"><button data-action="undo" ${state.history.length?'': 'disabled'}>${icon('undo')} 撤销</button><button data-action="redo" ${state.future.length?'': 'disabled'}>${icon('redo')} 重做</button></div>`:''}${item('rules','交通规则','signal')}${item('environment','天气照明','weather')}${item('incidents','事故与应急','warning')}${state.mode==='edit'?item('facilities','道路设施','lamp'):''}${item('demand','进车需求','car')}${item('driving','驾驶设置','settings')}${item('events','事件情景','warning')}${state.mode==='edit'?item('signals','路口信号','signal'):item('stats','运行统计','clock')}${item('garage','车型车库','car')}<div class="menu-divider"></div>${state.mode==='edit'?item('presets','路网模板','experiment'):item('save-record','保存本轮记录','save')}${item('records','实验记录','clock')}${item('theory','交通原理','info')}<div class="menu-divider"></div>${item('save','保存设计','save')}${state.mode==='edit'?item('load','读取设计','load')+item('import','导入设计','load'):''}${item('export','导出设计','download')}${state.mode==='edit'?item('clear','清空画布','trash'):''}</div>`);
}
function field(label,id,value,min,max,step=1){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="number" value="${value}" min="${min}" max="${max}" step="${step}" required></div>`;}
function openDemand(){setPanel('进车需求',`<p>所有入口共用总进车量，车辆请求按入口均匀分配。各入口独立排队，拥堵入口不阻塞其他入口。</p><div class="field"><div class="range-heading"><label for="demand">总进车量</label><output id="demand-output">${state.settings.demand} 辆/分</output></div><input type="range" id="demand" min="0" max="120" step="1" value="${state.settings.demand}"></div><div class="demand-presets">${[12,40,80,120].map(n=>`<button data-demand-preset="${n}">${n} 辆/分</button>`).join('')}</div><p>增大进车量可观察排队形成。设为 0 后，已排队和已进入道路的车辆继续通行。</p>`,'<button class="primary" data-action="apply-demand">完成</button>');}
function portControls(road){
  const ports=['source','sink'].flatMap(kind=>terminalIds(state.network,kind).filter(id=>id===road.a||id===road.b).map(id=>({kind,id})));
  return ports.length?`<h3>端口</h3><div class="port-controls">${ports.map(({kind,id})=>`<button data-remove-terminal="${kind}" data-terminal-id="${esc(id)}">移除${terminalLabel(state.network,kind,id)}</button>`).join('')}</div><p>入口与出口可分别设置多个，运行时至少各保留一个。</p>`:'';
}
function openDriving(){setPanel('驾驶设置',`<label class="check-row"><input type="checkbox" id="known-exit" ${state.settings.knownExit?'checked':''}>司机知道出口位置</label><p>开启后在可达出口间分配目标，并选择前往该出口的最短距离路线。关闭后沿相邻道路探索，经任一出口完成行程。</p><h3>自由流期望速度</h3><button class="parameter-link" data-action="parameter-info">参数依据与适用范围</button><p>单位：km/h。实际速度受道路限速、前车和信号控制。</p>${VEHICLE_TYPES.map(t=>`<div class="speed-row"><label for="speed-${t.id}">${t.name}</label><input type="range" id="speed-${t.id}" data-speed-type="${t.id}" min="5" max="140" step="1" value="${state.settings.speeds[t.id]}"><output id="value-${t.id}">${state.settings.speeds[t.id]}</output></div>`).join('')}`,'<button class="primary" data-action="apply-driving">完成</button>');}
function openParameterInfo(){setPanel('参数依据',`<p>汽车与卡车采用论文参考参数组，公交另用乘客舒适约束。速度设置表示自由流期望速度，实际仍受道路限速和交通条件约束。</p><div class="profile-evidence">${VEHICLE_TYPES.map(t=>`<div><strong>${t.name}</strong><span>${t.maxSpeed} km/h · 跟驰时距 ${t.timeHeadway} s</span><small>加速 ${t.accel} / 舒适制动 ${t.brake} m/s²</small></div>`).join('')}</div><p>轻型商用车与公交的部分参数采用分组代理；天气制动倍率、视距和路口处理仍含工程假设，尚未经过当地道路观测校准。</p>${PARAMETER_SOURCES.filter(x=>['ACC2007','BUS_COMFORT','FHWA_WEATHER'].includes(x.id)).map(x=>`<p><a href="${x.url}" target="_blank" rel="noopener">${x.title}</a></p>`).join('')}`);}
function openEvents(){const labels={speeding:'超速倾向',hesitation:'犹豫减速',parking:'临时停车',priority:'路口抢先申请'};setPanel('事件情景',`<div class="settings-note">演示假设，非实测概率。每辆成功入网车辆，每次行程抽取一次。</div>${['breakdown','violation'].map((id,i)=>`<div class="field"><div class="range-heading"><label for="${id}">${i?'违规概率':'故障概率'}</label><output id="${id}-output">${state.settings[id]}%</output></div><input type="range" id="${id}" min="0" max="100" value="${state.settings[id]}"></div>`).join('')}<h3>允许的违规类型</h3>${Object.entries(labels).map(([id,name])=>`<label class="check-row"><input type="checkbox" data-violation="${id}" ${state.settings.violations.includes(id)?'checked':''}>${name}</label>`).join('')}<p>命中违规时从已勾选类型中选择一项。路口抢先申请仍需遵守红灯和安全间距。</p>`,'<button class="primary" data-action="apply-events">完成</button>');}
function openRoad(id){const road=state.network.roads.find(r=>r.id===id);if(!road)return;state.selectedRoad=id;state.draft=clone(road);const terminal=terminalIds(state.network,'source').includes(road.a)||terminalIds(state.network,'sink').includes(road.b);view.setNetwork(state.network,id);setPanel('道路设置',`<div class="profile-list">${[['slow','慢行道路',30],['local','普通道路',50],['main','快速道路',70]].map(([type,name,speed])=>`<button data-road-type="${type}" data-limit="${speed}" class="${type===road.type?'active':''}">${icon('road')}${name}<strong>${speed}</strong></button>`).join('')}</div><div class="settings-note">弧长 ${roadPath(state.network,road).length.toFixed(1)} 米</div>${field('限速 · km/h','road-limit',road.speedLimit,5,100)}<div class="field"><label for="road-direction">通行方向</label><select id="road-direction" ${terminal?'disabled':''}>${terminal?'<option value="one" selected>端口固定单向</option>':`<option value="both" ${!road.oneWay?'selected':''}>双向通行</option><option value="one" ${road.oneWay?'selected':''}>单向通行</option>`}</select></div><h3>车道配置</h3>${laneControls('road',road)}${portControls(road)}<p>车道配置会改变道路宽度和实际运行车道。正向为道路绘制方向。</p>`,'<button class="primary" data-action="apply-road">完成</button>');state.draft=clone(road);updateLaneForm('road');}

function signalOptions(){return state.network.nodes.filter(n=>state.network.roads.filter(r=>r.a===n.id||r.b===n.id).length>=2);}
function openSignal(id){const nodes=signalOptions();if(!nodes.length){toast('先绘制一个连接两条以上道路的节点');return;}const node=nodes.find(n=>n.id===id)||nodes[0];state.selectedNode=node.id;const signal=state.network.signals[node.id]||{enabled:false,greenEW:20,greenNS:20,yellow:3,allRed:1,offset:0};setPanel('路口信号',`<div class="field"><label for="signal-node">选择路口</label><select id="signal-node">${nodes.map((n,i)=>`<option value="${n.id}" ${n.id===node.id?'selected':''}>路口 ${i+1} · ${n.x} / ${n.z} 米</option>`).join('')}</select></div><label class="check-row"><input type="checkbox" id="signal-enabled" ${signal.enabled?'checked':''}>启用交通信号</label><div class="signal-preview">${['ew','ns'].map((a,i)=>`<div class="signal-axis"><span>${i?'南北方向':'东西方向'}</span><div class="signal-lamps" id="preview-${a}"><i class="lamp red"></i><i class="lamp yellow"></i><i class="lamp green"></i></div></div>`).join('')}</div>${field('东西绿灯 · 秒','greenEW',signal.greenEW,1,120)}${field('南北绿灯 · 秒','greenNS',signal.greenNS,1,120)}${field('黄灯 · 秒','yellow',signal.yellow,1,10)}${field('全红清空 · 秒','allRed',signal.allRed,.5,10,.5)}<p>上方预览使用独立时钟。运行时以同一控制器决定灯色和车辆通行权。</p>`,'<button class="primary" data-action="apply-signal">完成</button>');state.draft=clone(signal);previewClock=0;}
function openPresets(){if(state.mode!=='edit')return;setPanel('路网模板',`<p>选择模板后直接载入画布，可继续编辑。Ctrl Z 撤销载入。</p><div class="template-list">${templates.map(t=>`<button data-template="${t.id}"><span class="template-icon">${icon(t.model==='signal'||t.id==='signal'?'signal':t.id==='roundabout'?'circle':'road')}</span><span><strong>${t.title}</strong><small>${t.detail}</small></span><span class="template-arrow">↗</span></button>`).join('')}</div>`,'<button data-action="theory">交通原理与动画</button>');}
async function loadPreset(name){const apply=()=>{editor.cancel(true);closePanel();commit(createPreset(name));state.anchor=null;state.tool='road';editor.defaultHint();view.fit();refresh();toast('示例已载入，可继续编辑道路或开始运行');};if(state.network.roads.length)await confirmDialog('载入示例路网','当前设计将由示例替换。可以通过撤销恢复当前路网。','载入示例',apply);else apply();}
async function startRun(){if(state.mode!=='edit')return;const check=validateNetwork(state.network);if(!check.valid){toast(check.reason,true);return;}closePanel();state.anchor=null;view.setPreview([]);try{state.simulation=createSimulation(state.network,state.settings);}catch(error){toast(error.message,true);return;}state.runNetwork=clone(state.network);state.runSettings=clone(state.settings);editor.cancel(true);state.mode='transition';state.running=false;state.speed=1;refresh();await view.transitionToRun();state.mode='run';state.running=true;accumulator=0;previous=performance.now();refresh();}
function returnToEdit(){confirmDialog('回到设计','本轮车流与统计将清空，路网和设置保留。可先从菜单保存实验记录。','回到设计',()=>{closePanel();state.running=false;state.simulation=null;state.mode='edit';state.panelWasRunning=false;view.setMode('edit');view.setNetwork(state.network);refresh();});}
function openGarage(){const previousMode=state.mode;const wasRunning=state.panel?state.panelWasRunning:state.running;closePanel();state.garageReturn={mode:previousMode,running:wasRunning};state.mode='garage';state.running=false;selectGarage(state.garageType);$('#garage-return').lastChild.textContent=previousMode==='run'?'返回运行':'返回设计';refresh();}
function selectGarage(id){state.garageType=id;const t=VEHICLE_TYPES.find(t=>t.id===id);view.setGarage(id);$('#garage-name').textContent=t.name;$('#garage-size').textContent=`长 ${t.length.toFixed(1)} 米 · 宽 ${t.width.toFixed(1)} 米` ;$$('[data-vehicle]').forEach(b=>b.classList.toggle('active',b.dataset.vehicle===id));}
function returnGarage(){state.mode=state.garageReturn?.mode||'edit';state.running=state.garageReturn?.running||false;view.setMode(state.mode);if(state.mode==='run')view.update(state.simulation.snapshot());else view.setNetwork(state.network);view.fit();refresh();}
if(typeof window!=='undefined'){window.openRoad=openRoad;window.openSignal=openSignal;window.setPanel=setPanel;window.closePanel=closePanel;window.openGarage=openGarage;window.loadPreset=loadPreset;}
function updateSettings(partial,{restart=false}={}){const settings={...state.settings,...partial,speeds:{...state.settings.speeds,...partial.speeds}};try{parseDesign(JSON.stringify({version:1,network:state.network,settings}));}catch(error){toast(error.message,true);return;}const apply=()=>{state.settings=settings;if(state.mode==='run'&&restart){state.simulation=createSimulation(state.network,settings);state.runSettings=clone(settings);view.clearCars();accumulator=0;}else state.simulation?.updateSettings(partial);closePanel();toast(restart&&state.mode==='run'?'已按新设置重新开始本轮':'设置已更新');};if(restart&&state.mode==='run')confirmDialog('重新开始本轮','这项设置会改变车辆的行程行为。确认后清空本轮统计并重新开始。','重新开始',apply);else apply();}

function statRows(stats,time){return `<dl class="stats-list"><dt>模拟时间</dt><dd>${time.toFixed(1)} 秒</dd><dt>请求车辆</dt><dd>${stats.requested}</dd><dt>入口积压</dt><dd>${stats.queued}</dd><dt>道路车辆</dt><dd>${stats.active}</dd><dt>已到达</dt><dd>${stats.arrived}</dd><dt>平均路上用时</dt><dd>${stats.meanTravelTime==null?'—':stats.meanTravelTime.toFixed(1)+' 秒'}</dd><dt>发生故障</dt><dd>${stats.breakdowns}</dd><dt>发生违规</dt><dd>${stats.violations}</dd><dt>事故清障移除</dt><dd>${stats.removed||0} 辆</dd><dt>碰撞</dt><dd>${stats.collisions||0}</dd><dt>转向车道受限</dt><dd>${stats.turnLaneBlocked||0} 辆</dd><dt>数值安全修正</dt><dd>${stats.safetyCorrections}</dd></dl>`;}
function portRows(stats){
  if(!stats.portStats)return '';
  const sources=terminalIds(state.network,'source'),sinks=terminalIds(state.network,'sink');
  return `<h3>入口分流</h3><dl class="stats-list">${sources.map(id=>{const p=stats.portStats.sources[id];return p?`<dt>${terminalLabel(state.network,'source',id)}</dt><dd data-port-stat="source:${esc(id)}">已进网 ${p.requested-p.queued} · 积压 ${p.queued}</dd>`:'';}).join('')}</dl><h3>出口到达</h3><dl class="stats-list">${sinks.map(id=>`<dt>${terminalLabel(state.network,'sink',id)}</dt><dd data-port-stat="sink:${esc(id)}">${stats.portStats.sinks[id]?.arrived||0} 辆</dd>`).join('')}</dl>`;
}
function openStats(){if(!state.simulation)return;const snap=state.simulation.snapshot();setPanel('运行统计',`${statRows(snap.stats,snap.time)}${portRows(snap.stats)}<p>等待包含各入口积压与道路上的低速车辆。平均路上用时只统计车尾已通过出口的完成车辆，不包含入网前等待。</p><p>当前模型为教学仿真，参数未经过现实道路标定。</p>`,'<button class="primary" data-action="save-record">保存本轮记录</button>');}
function openRoadTraffic(id){if(!state.simulation)return;const r=state.simulation.snapshot({includeEvents:false}).roadStats[id];if(!r)return;setPanel('路段拥堵情况',`<div class="congestion-card" data-level="${r.level}"><strong>${r.label}</strong><span>${r.vehicleCount} 辆在此路段</span></div><dl class="stats-list"><dt>平均车速</dt><dd>${r.meanSpeedKmh==null?'—':r.meanSpeedKmh.toFixed(1)+' km/h'}</dd><dt>自由行驶参考速度</dt><dd>${r.freeSpeedKmh.toFixed(1)} km/h</dd><dt>速度保持比例</dt><dd>${r.speedRatio==null?'—':(r.speedRatio*100).toFixed(0)+'%'}</dd><dt>低速排队车辆</dt><dd>${r.queuedVehicles} 辆</dd><dt>车道密度</dt><dd>${r.densityVehPerKm.toFixed(1)} 辆/km</dd></dl><p>密度按车道总长度计算。速度低于 3.6 km/h 的车辆计入本路段低速排队。</p><button class="subtle" style="padding:12px 18px" data-action="congestion-help">查看分级依据</button>`);}
function openCongestionHelp(){setPanel('拥堵如何显示',`<div class="congestion-card" data-level="free"><strong>绿色 · 畅通</strong><span>车辆按当前路段的正常速度通行</span></div><div class="congestion-card" data-level="slow"><strong>黄色 · 缓行</strong><span>平均速度低于参考速度的 70%，并出现多车或低速等待</span></div><div class="congestion-card" data-level="congested"><strong>红色 · 拥堵</strong><span>平均速度低于参考速度的 35%，同时存在较密集车流与排队</span></div><p>参考速度综合车型期望速度与道路限速，车辆密度按车道总长计算。单辆刚起步车辆不会仅因速度较低被判为拥堵。</p><p>红色分级还要求车身占用比例达到 8% 或车道密度达到 12 辆/km，并满足至少 3 辆在途，或至少 2 辆低速排队且排队比例达到 35%。这些是本游戏的展示规则。</p><p>点击运行画面中的道路可查看该路段车速、密度和排队数量。入口外的积压单独计入“等待”。</p>`);}
function saveRecord(){if(!state.simulation)return;const snap=state.simulation.snapshot();const record={id:Date.now(),title:`实验 ${state.records.length+1}`,createdAt:new Date().toLocaleString('zh-CN'),modelVersion:MODEL_VERSION,network:clone(state.runNetwork),settings:clone(state.runSettings),time:snap.time,stats:snap.stats,events:snap.events};state.records.push(record);state.records=state.records.slice(-12);try{localStorage.setItem(recordKey,JSON.stringify(state.records));toast('本轮记录已保存');}catch{toast('浏览器存储不足，记录仍可在本次会话导出',true);}openRecords();}
function openRecords(){const records=[...state.records].reverse();setPanel('实验记录',records.length?`${records.slice(0,2).length===2?`<h3>最近两次对照</h3><div class="settings-note">${records[1].time.toFixed(0)} 秒 / ${records[0].time.toFixed(0)} 秒<br>完成 ${records[1].stats.arrived} / ${records[0].stats.arrived} 辆<br>入口积压 ${records[1].stats.queued} / ${records[0].stats.queued} 辆</div><p>比较前应确认观测时长、需求和随机种子一致。</p>`:''}${records.map(r=>`<div class="record-card"><h3>${esc(r.title)} · ${r.time.toFixed(1)} 秒</h3><p>${esc(r.createdAt)}</p><p>已到达 ${r.stats.arrived} · 在途 ${r.stats.active} · 入口 ${r.stats.queued}</p><p>平均路上用时 ${r.stats.meanTravelTime==null?'—':r.stats.meanTravelTime.toFixed(1)+' 秒'}</p><button data-record-export="${r.id}">${icon('download')} 导出记录</button>${state.mode==='edit'?` <button data-record-load="${r.id}">载入配置</button>`:''}</div>`).join('')}`:'<h3>尚无实验记录</h3><p>开始运行后，从菜单保存当前统计。记录包含路网、随机种子、运行设置与事件。</p>');}
function saveDesign(){const text=JSON.stringify({version:1,network:state.network,settings:state.settings},null,2);try{localStorage.setItem(storageKey,text);toast('设计已保存到此浏览器');}catch{toast('本地保存失败，可使用导出设计保存文件',true);}}
function loadDesign(){let text;try{text=localStorage.getItem(storageKey);}catch{toast('当前浏览器不允许读取本地存储',true);return;}if(!text){toast('此浏览器尚无已保存设计');return;}applyImport(text);}
function applyImport(text){try{const result=parseDesign(text);closePanel();commit(result.network);state.settings=result.settings;state.anchor=null;state.tool='road';view.fit();refresh();toast('设计已载入');}catch(error){toast(error.message,true);}}
function download(data,name){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function confirmDialog(title,body,label,apply){return new Promise(resolve=>{const host=$('#dialog-host');host.innerHTML=`<div class="dialog-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${esc(title)}</h2><p>${esc(body)}</p><div class="dialog-actions"><button id="dialog-cancel">取消</button><button id="dialog-confirm" class="primary">${esc(label)}</button></div></section></div>`;const was=state.running;state.running=false;const finish=ok=>{host.innerHTML='';state.running=was;if(ok)apply();refresh();resolve(ok);};$('#dialog-cancel').onclick=()=>finish(false);$('#dialog-confirm').onclick=()=>finish(true);$('#dialog-cancel').focus();});}

document.addEventListener('click',async e=>{
  const button=e.target.closest('button,[data-action]');if(!button||button.disabled)return;
  if(button.dataset.theoryTab){theory.open(button.dataset.theoryTab);return;}
  if(button.dataset.theoryVariant){theory.variant=button.dataset.theoryVariant;theory.open('braess');return;}
  if(button.dataset.laneCount){updateLaneForm(button.dataset.laneForm,Number(button.dataset.laneCount));return;}
  if(button.dataset.template){loadTemplate(button.dataset.template);return;}
  if(button.dataset.tool){setTool(button.dataset.tool);return;}
  if(button.dataset.buildTab){state.buildTab=button.dataset.buildTab;setTool(state.buildTab==='facilities'?'facility':'road');return;}
  if(button.dataset.shape){closePanel();editor.setShape(button.dataset.shape);return;}
  if(button.dataset.snap){state[button.dataset.snap]=!state[button.dataset.snap];refresh();return;}
  if(button.dataset.newRoadType){state.newRoadType=button.dataset.newRoadType;$('#new-road-limit').value=button.dataset.limit;$$('[data-new-road-type]').forEach(b=>b.classList.toggle('active',b===button));return;}
  if(button.dataset.speed){state.speed=Number(button.dataset.speed);accumulator=0;rateWindowStart=performance.now();rateSimStart=state.simulation?.snapshot({includeEvents:false}).time||0;refresh();return;}
  if(button.dataset.demandPreset){$('#demand').value=button.dataset.demandPreset;$('#demand-output').textContent=`${button.dataset.demandPreset} 辆/分`;return;}
  if(button.dataset.vehicle){selectGarage(button.dataset.vehicle);return;}
  if(button.dataset.roadType){state.draft.type=button.dataset.roadType;$('#road-limit').value=button.dataset.limit;$$('[data-road-type]').forEach(b=>b.classList.toggle('active',b===button));return;}
  if(button.dataset.recordExport){const record=state.records.find(r=>r.id===Number(button.dataset.recordExport));download(record,`交通实验-${record.id}.json`);return;}
  if(button.dataset.recordLoad){const record=state.records.find(r=>r.id===Number(button.dataset.recordLoad));applyImport(JSON.stringify(record));return;}
  if(button.dataset.removeTerminal){const kind=button.dataset.removeTerminal,id=button.dataset.terminalId,label=terminalLabel(state.network,kind,id);closePanel();commit(removeEndpoint(state.network,kind,id));editor.defaultHint();toast(`已移除${label}`);return;}
  const action=button.dataset.action;
  const actions={menu:openMenu,'close-panel':closePanel,undo:()=>{closePanel();undo();},redo:()=>{closePanel();redo();},start:startRun,pause:()=>{state.running=!state.running;refresh();},return:returnToEdit,'zoom-in':()=>view.zoom(.8),'zoom-out':()=>view.zoom(1.25),fit:()=>view.fit(),demand:openDemand,driving:openDriving,'parameter-info':openParameterInfo,events:openEvents,signals:()=>openSignal(),presets:openPresets,garage:openGarage,'garage-return':returnGarage,stats:openStats,records:openRecords,'save-record':saveRecord,theory:()=>theory.open(),'theory-pause':()=>theory.toggle(),save:saveDesign,load:loadDesign,import:()=>$('#import-file').click(),export:()=>download({version:1,network:state.network,settings:state.settings},'堵车实验室-设计.json'),clear:()=>confirmDialog('清空画布','清空当前路网后可以通过撤销恢复。','清空',()=>{closePanel();commit(emptyNetwork());setTool('source');view.fit();}),fallback:()=>{view.enableFallback();closePanel();refresh();},'preset-fork':()=>loadPreset('fork'),'preset-signal':()=>loadPreset('signal'),'preset-bottleneck':()=>loadPreset('bottleneck'),'apply-demand':()=>updateSettings({demand:Number($('#demand').value)}),'apply-driving':()=>{const knownExit=$('#known-exit').checked,speeds=Object.fromEntries(VEHICLE_TYPES.map(t=>[t.id,Number($(`#speed-${t.id}`).value)]));updateSettings({knownExit,speeds},{restart:knownExit!==state.settings.knownExit});},'apply-events':()=>updateSettings({breakdown:Number($('#breakdown').value),violation:Number($('#violation').value),violations:$$('[data-violation]:checked').map(el=>el.dataset.violation)},{restart:true}),'apply-seed':()=>updateSettings({seed:Number($('#experiment-seed').value)}),'apply-road':()=>{const n=clone(state.network),road=n.roads.find(r=>r.id===state.selectedRoad);road.type=state.draft.type;road.speedLimit=Number($('#road-limit').value);Object.assign(road,laneForm('road'));for(const f of n.facilities||[]){if(f.roadId===road.id){const p=roadPointAt(n,road,f.s,(f.side||1)*(road.width/2+(f.type==='trafficLight'?1.4:1.6)));f.x=p.x;f.z=p.z;if(f.type!=='trafficLight')f.heading=p.yaw;}}try{const valid=parseDesign(JSON.stringify({network:n,settings:state.settings}));const issue=junctionIssues(valid.network)[0];if(issue&&!junctionIssues(state.network).length)throw new Error(`${issue.message}。请减少车道或延长相邻道路。`);closePanel();commit(valid.network);}catch(error){toast(error.message,true);}},'apply-signal':()=>{const n=clone(state.network);n.signals[state.selectedNode]={enabled:$('#signal-enabled').checked,greenEW:Number($('#greenEW').value),greenNS:Number($('#greenNS').value),yellow:Number($('#yellow').value),allRed:Number($('#allRed').value),offset:state.draft.offset||0};try{const result=parseDesign(JSON.stringify({network:n,settings:state.settings}));closePanel();commit(result.network);}catch(error){toast(error.message,true);}}};
  if(action==='toggle-view'){state.editView=state.editView==='2d'?'3d':'2d';if(state.editView==='3d'){state.tool='select';editor.setTool('select');}view.setEditingPerspective(state.editView==='3d');editor.defaultHint();refresh();return;}
  if(action==='toggle-heatmap'){state.heatmap=!state.heatmap;refresh();return;}
  if(action==='construction-settings'){openConstruction();return;}
  if(action==='apply-construction'){try{const limit=Number($('#new-road-limit').value);if(!Number.isFinite(limit)||limit<5||limit>100)throw new Error('道路限速需在 5 至 100 km/h');const road=laneForm('new');state.newRoadSpeed=limit;state.newLanesForward=road.lanesForward;state.newLanesBackward=road.lanesBackward;state.newTurnsForward=road.turnsForward;state.newTurnsBackward=road.turnsBackward;state.roadWidth=road.width;state.newOneWay=road.oneWay;$$('[data-snap-check]').forEach(c=>state[c.dataset.snapCheck]=c.checked);closePanel();refresh();}catch(error){toast(error.message,true);}return;}

  if(action==='congestion-help'){openCongestionHelp();return;}if(['preset-roundabout','preset-accident'].includes(action)){await loadPreset(action.replace('preset-',''));return;}if(actions[action])await actions[action]();
});
document.addEventListener('input',e=>{if(e.target.id==='demand')$('#demand-output').textContent=`${e.target.value} 辆/分`;if(['breakdown','violation'].includes(e.target.id))$(`#${e.target.id}-output`).textContent=`${e.target.value}%`;if(e.target.dataset.speedType)$(`#value-${e.target.dataset.speedType}`).textContent=e.target.value;});
document.addEventListener('change',e=>{if(e.target.id==='new-road-oneway'||e.target.id==='road-direction'){const prefix=e.target.id==='new-road-oneway'?'new':'road',total=Number($(`#${prefix}-lanes-forward`).value)+Number($(`#${prefix}-lanes-backward`).value);const control=e.target;const oneWay=prefix==='new'?control.checked:control.value==='one';updateLaneForm(prefix,Math.max(oneWay?1:2,total));}if(e.target.id?.includes('-lanes-'))updateLaneForm(e.target.id.startsWith('new-')?'new':'road');if(e.target.id==='signal-node')openSignal(e.target.value);});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(file){if(file.size>1000000)toast('设计文件不能超过 1 MB',true);else applyImport(await file.text());}e.target.value='';});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#dialog-cancel')){$('#dialog-cancel').click();return;}if(state.panel)closePanel();else if(state.mode==='garage')returnGarage();else{editor.cancel();refresh();}return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveDesign();}if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if(state.mode==='edit'&&!state.panel){const tool={v:'select',b:'road',d:'erase'}[e.key.toLowerCase()];if(tool){e.preventDefault();setTool(tool);}}if(e.code==='Space'&&state.mode==='run'&&!state.panel){e.preventDefault();state.running=!state.running;refresh();}if(e.key==='Enter'&&e.target.id==='hud')openStats();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.mode==='run'){state.running=false;state.panelWasRunning=false;refresh();toast('已暂停，返回后可继续运行');}previous=performance.now();accumulator=0;});

let previous=performance.now(),accumulator=0,lastHud=0,previewClock=0,rateWindowStart=performance.now(),rateSimStart=0,actualRate=1;
function animate(now){const dt=Math.min(.1,Math.max(0,(now-previous)/1000));previous=now;
  if(state.mode==='run'&&state.simulation){if(state.running&&!document.hidden){accumulator+=dt*state.speed;const deadline=performance.now()+9;let steps=0;while(accumulator>=.05&&steps<600){state.simulation.step(.05);accumulator-=.05;steps++;if(steps%10===0&&performance.now()>deadline)break;}accumulator=Math.min(accumulator,.25);}const snap=state.simulation.snapshot({includeEvents:false});view.update(snap);
    if(now-rateWindowStart>=1000){actualRate=Math.max(0,(snap.time-rateSimStart)/((now-rateWindowStart)/1000));rateWindowStart=now;rateSimStart=snap.time;}
    if(now-lastHud>150){$('#stat-waiting').textContent=snap.stats.waiting;$('#stat-arrived').textContent=snap.stats.arrived;$('#stat-travel').textContent=snap.stats.meanTravelTime==null?'—':`${snap.stats.meanTravelTime.toFixed(0)}秒`;$('#sim-status').textContent=`${state.panel?'设置中 · 已暂停':state.running?'运行中':'已暂停'} · ${snap.time.toFixed(1)} 秒 · 在途 ${snap.stats.active}${snap.stats.turnLaneBlocked?` · 转向受限 ${snap.stats.turnLaneBlocked} 辆`:""}`;
      const blocked=snap.stats.congestedRoads||0,slow=snap.stats.slowRoads||0;$('#traffic-status').dataset.level=blocked?'congested':slow?'slow':snap.stats.active?'free':'empty';$('#traffic-summary').textContent=blocked?`拥堵 ${blocked} 段 · 缓行 ${slow} 段`:slow?`缓行 ${slow} 段 · 暂无拥堵`:'路网畅通';const incidents=snap.incidents||[];$('#incident-pill').classList.toggle('hidden',!incidents.length);$('#incident-pill').textContent=`事故 ${incidents.length} 起`;$('#actual-speed').textContent=state.running?`目标 ${state.speed}× · 实际 ${actualRate.toFixed(1)}×`:'模拟已暂停';lastHud=now;
    }}
  if(state.panel==='路口信号'){previewClock+=dt;const cfg={enabled:$('#signal-enabled').checked,greenEW:Number($('#greenEW').value),greenNS:Number($('#greenNS').value),yellow:Number($('#yellow').value),allRed:Number($('#allRed').value)};const phases=signalPhase(cfg,previewClock);for(const a of['ew','ns'])$$(`#preview-${a} .lamp`).forEach(l=>l.classList.toggle('on',cfg.enabled&&l.classList.contains(phases[a])));}
  if(state.panel==='交通原理')theory.update(now);
  view.render();requestAnimationFrame(animate);
}
view.setNetwork(state.network);refresh();editor.defaultHint();requestAnimationFrame(animate);
